import{_ as a,o,c as s,a2 as n}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Equipo y botín","description":"","frontmatter":{},"headers":[],"relativePath":"es/game-design/equipment-and-loot.md","filePath":"es/game-design/equipment-and-loot.md"}'),i={name:"es/game-design/equipment-and-loot.md"};function r(t,e,d,c,l,p){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="equipment-and-loot" tabindex="-1">Equipo y botín <a class="header-anchor" href="#equipment-and-loot" aria-label="Enlace permanente a &quot;Equipo y botín&quot;">​</a></h1><p><strong>Estado del diseño: Aceptado para la dirección general; Propuesto para las funciones de familias y excepciones de conservación. Implementación: solo objetos/durabilidad/botín heredados.</strong></p><p>Favorecer equipo reemplazable, horizontal y pérdidas significativas. Los seguros amplios al estilo AOS no son la dirección elegida. Un posible Sacred Item único conservado mediante un sistema de sacerdotes <strong>no está aprobado</strong>; las funciones de sacerdotes y las reglas de conservación siguen siendo diseño futuro.</p><p>La armadura heredada puede proteger ambos lados con un solo objeto de mangas/perneras/guantes, mientras cada extremidad tiene integridad independiente. La durabilidad compartida pertenece a ese objeto. El contacto con Hands y con Arms es distinto; destruir las mangas no elimina la protección de los guantes.</p><p>Las identidades de armas con estado Propuesto incluyen precisión de dagas, flexibilidad de espadas, fuerza contundente de mazas/martillos de guerra, corte/presión sobre equipo de hachas y alcance de lanzas. Son direcciones, no bonificaciones ni balance definitivos.</p><p><strong>Brecha:</strong> la absorción/desgaste heredados pueden sustentar el primer adaptador, pero materiales, nuevas reglas de botín y propagación específica por arma no están implementados ni forman parte de Slice 0. La discapacidad que afecta al escudo conserva la propiedad y las reglas existentes de muerte/botín.</p><h2 id="proposed-spellbook-exception" tabindex="-1">Excepción para el libro de hechizos — Propuesto <a class="header-anchor" href="#proposed-spellbook-exception" aria-label="Enlace permanente a &quot;Excepción para el libro de hechizos — Propuesto&quot;">​</a></h2><p>La <a href="/Syrolands-Public/es/game-design/magic/spellbooks-scrolls-and-reagents.html#death-and-material-risk">especificación de materiales mágicos</a> protege el conocimiento aprendido permanentemente con independencia del botín físico y propone que el libro personal básico normalmente no caiga. Los grimorios/manuscritos físicos raros pueden saquearse; pergaminos y reactivos son recursos físicos que generalmente caen al morir. La representación/reposición personal exacta, políticas de libros raros y valor del material preparado permanecen Sin resolver. Esto no aprueba seguros amplios, conservación de Sacred Item, modificadores protegidos ni un mecanismo de bendición. <a href="/Syrolands-Public/es/game-design/professions/inscription.html">Inscription</a> define la función artesanal propuesta; los gestores de muerte existentes no cambian.</p><h2 id="proposed-craft-quality-and-item-history" tabindex="-1">Calidad artesanal e historia de objetos — Propuesto <a class="header-anchor" href="#proposed-craft-quality-and-item-history" aria-label="Enlace permanente a &quot;Calidad artesanal e historia de objetos — Propuesto&quot;">​</a></h2><p><a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html">Objetos y calidad artesanal</a> define el lenguaje compartido de calidad artesanal/botín del Batch 01, rangos posibles, dimensiones compactas de armas, Masterworks raros, rasgos y resonancia latente. <a href="/Syrolands-Public/es/game-design/professions/profession-system.html">Profesiones</a> define producción y reputación. Estas propuestas preservan equipo horizontal y pérdidas significativas; ningún objeto heredado ni fórmula de combate actual cambia.</p><p>Los futuros Sacred/Resonant Sets tratan la sinergia entre objetos compatibles, <strong>no</strong> la aprobación de la propuesta separada de conservación de Sacred Item. Su escasez, poder, nombres y comportamiento ante la pérdida requieren <a href="/Syrolands-Public/es/game-design/items/itemization-and-craft-quality.html#open-questions-and-reconciliation">conciliación explícita</a>.</p><h2 id="combat-foundation-cross-links" tabindex="-1">Enlaces de fundamentos del combate <a class="header-anchor" href="#combat-foundation-cross-links" aria-label="Enlace permanente a &quot;Enlaces de fundamentos del combate&quot;">​</a></h2><p>Las <a href="/Syrolands-Public/es/game-design/combat/weapons-and-damage.html">identidades de armas</a> y las <a href="/Syrolands-Public/es/game-design/combat/armor-and-mitigation.html">interacciones de armadura/material/estado</a> amplían las funciones de combate con estado Propuesto. La calidad artesanal y el mantenimiento deben conservar la dirección aceptada de pérdida/reemplazabilidad; Masterworks y rasgos especiales no implican seguros. Penetración exacta, transmisión de trauma y desgaste funcional siguen sin resolverse, con la <a href="/Syrolands-Public/es/game-design/combat/damage.html">política de trauma</a> experimental intacta.</p>',13)])])}const g=a(i,[["render",r]]);export{u as __pageData,g as default};
